alter table profiles add column if not exists tags text[] not null default '{}';
create or replace function is_staff() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role in ('admin','moderator')) $$;
drop policy if exists "own profile update" on profiles;
create policy "own profile update" on profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid() and role=(select role from profiles where id=auth.uid()) and tags=(select tags from profiles where id=auth.uid()));
create or replace function set_tags(uid uuid, new_tags text[]) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from profiles where id=auth.uid() and role='admin') then raise exception 'Only admins can change tags'; end if; update profiles set tags=(select coalesce(array_agg(t),'{}') from unnest(new_tags) t where t in ('trusted','verified','mentor','helper')) where id=uid; end $$;
create table if not exists messages(id uuid primary key default gen_random_uuid(), response_id uuid not null references request_responses on delete cascade, sender uuid not null references profiles on delete cascade default auth.uid(), body text not null check (char_length(body) between 1 and 2000), created_at timestamptz default now());
create index if not exists messages_resp on messages(response_id, created_at);
alter table messages enable row level security;
create policy "chat read" on messages for select to authenticated using (exists(select 1 from request_responses rr join requests r on r.id=rr.request_id where rr.id=response_id and (rr.responder=auth.uid() or r.owner=auth.uid())));
create policy "chat send" on messages for insert to authenticated with check (sender=auth.uid() and exists(select 1 from request_responses rr join requests r on r.id=rr.request_id where rr.id=response_id and (rr.responder=auth.uid() or r.owner=auth.uid()) and r.status not in ('completed','cancelled','closed')));
alter publication supabase_realtime add table messages;
create table if not exists news(id uuid primary key default gen_random_uuid(), author uuid references profiles on delete set null default auth.uid(), kind text not null default 'news' check (kind in ('announcement','news','photo','video')), title text not null check (char_length(title) between 3 and 140), body text, media_url text, media_type text check (media_type in ('image','video','youtube')), created_at timestamptz default now());
alter table news enable row level security;
create policy "news read" on news for select to anon, authenticated using (true);
create policy "news staff insert" on news for insert to authenticated with check (is_staff());
create policy "news staff update" on news for update to authenticated using (is_staff()) with check (is_staff());
create policy "news staff delete" on news for delete to authenticated using (is_staff());
insert into storage.buckets(id,name,public) values('news','news',true) on conflict do nothing;
create policy "news files read" on storage.objects for select using (bucket_id='news');
create policy "news files staff upload" on storage.objects for insert to authenticated with check (bucket_id='news' and is_staff());
create policy "news files staff delete" on storage.objects for delete to authenticated using (bucket_id='news' and is_staff());
